@app.get("/api/v1/webrtc/consultations/{consultation_id}/token")
async def get_consultation_signaling_token(
    consultation_id: int,
    token_generator: SignalingTokenService = Depends(get_signaling_token_service),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    consultation = await db.get(TelehealthSession, consultation_id)
    if not consultation:
        raise HTTPException(status_code=404, detail="Consultation session not found")
    if current_user.id not in (consultation.patient_id, consultation.doctor_id):
        raise HTTPException(status_code=403, detail="Forbidden: You are not a participant in this consultation")
    ephemeral_token = token_generator.create_room_token(
        room_name=consultation.room_name,
        user_identity=str(current_user.id)
    )
    return {"token": ephemeral_token, "room_name": consultation.room_name}
